### ILI Computation Functions

```javascript
function computeILI(stateAbbrev) {
  const scores = ILI_SCORES[stateAbbrev];
  if (!scores) return estimateILI(stateAbbrev);

  return {
    campaignFinance: scores.campaignFinance,
    ethicsVacuum: scores.ethicsVacuum,
    darkMoney: scores.darkMoney,
    regulatoryCapture: scores.regulatoryCapture,
    total: scores.total,
    narrative: scores.narrative,
    category: categorizeILI(scores.total),
  };
}

function categorizeILI(total) {
  if (total >= 70) return { label: "Influence Laundering Haven", color: "#8B0000", icon: "🏦" };
  if (total >= 50) return { label: "High Corruption Risk", color: "#e74c3c", icon: "🔴" };
  if (total >= 30) return { label: "Moderate Corruption Risk", color: "#f39c12", icon: "🟠" };
  if (total >= 15) return { label: "Low Corruption Risk", color: "#f1c40f", icon: "🟡" };
  return { label: "Clean Government", color: "#2ecc71", icon: "🟢" };
}

function estimateILI(stateAbbrev) {
  // Heuristic estimation for states not individually researched
  const state = STATES.find(s => s.abbrev === stateAbbrev);
  if (!state) return null;

  // States with no contribution limits get high campaign finance scores
  const unlimitedStates = ["AL", "IN", "IA", "MS", "NE", "ND", "OR", "PA", "TX", "UT", "VA"];
  let campaignFinance = unlimitedStates.includes(stateAbbrev) ? 22 : 10;

  // States with no independent ethics agency
  const noEthicsAgency = ["AZ", "ID", "WY"];
  let ethicsVacuum = noEthicsAgency.includes(stateAbbrev) ? 25 : 12;

  // Default moderate scores for unresearched states
  let darkMoney = 14;
  let regulatoryCapture = 12;

  const total = campaignFinance + ethicsVacuum + darkMoney + regulatoryCapture;

  return {
    campaignFinance, ethicsVacuum, darkMoney, regulatoryCapture,
    total,
    narrative: "Estimated — not individually researched. Based on contribution limit status and ethics agency existence.",
    category: categorizeILI(total),
    estimated: true,
  };
}
```

