## 🧪 The Complete Browser Probe Protocol

```javascript
class BrowserMeridianNode {
  // Ring members: Map<peerId, { dc: DataChannel, rtt: number, ring: number }>
  rings = Array(9).fill(null).map(() => []);

  async measureRtt(target) {
    // Fast path: target is already a ring member
    if (this.rings.some(r => r.includes(target))) {
      const peer = this.peers.get(target);
      return await measureRtt(peer.dc);  // ~1ms
    }

    // Medium path: target is a known peer (not in rings)
    if (this.knownPeers.has(target)) {
      return await this.establishAndProbe(target);  // ~500ms-2s
    }

    // Slow path: target is a web server or unknown
    if (target.startsWith('http')) {
      return await probeHttpTarget(target);  // ~50-200ms
    }

    // Unknown peer — use signaling server to facilitate ephemeral connection
    return await this.probeViaSignaling(target);  // ~500ms-2s
  }

  async handleProbeRequest(query) {
    // Called when another node asks us to measure RTT to a target
    const rtt = await this.measureRtt(query.target);
    query.sourceDc.send(JSON.stringify({
      type: 'probe_result',
      query_id: query.query_id,
      rtt_ms: rtt
    }));
  }

  async handleQuery(query) {
    // Meridian query routing
    const myRtt = await this.measureRtt(query.target);

    // Find the right ring
    const ringIndex = Math.floor(Math.log2(myRtt));

    // Ask ring members to probe (in parallel)
    const results = await Promise.all(
      this.rings[ringIndex].map(peerId => 
        this.askPeerToProbe(peerId, query.target)
      )
    );

    // Find closest
    const closest = results.reduce((best, r) => 
      r.rtt < best.rtt ? r : best
    );

    // Forward if progress meets threshold (β = 0.5)
    if (closest.rtt < myRtt * 0.5) {
      closest.peer.handleQuery(query);
    } else {
      query.respond({ closest_peer: this.peerId, rtt: myRtt });
    }
  }
}
```

