### Operations

**Insert (on failed Find_Value):**

```typescript
function insertMemory(ebf: EBF, wheel: TimingWheel, blockId: Hash): void {
  const { fp, index } = hashToEBF(blockId, ebf.size);

  // Check for duplicate
  if (ebf.buckets[index].fingerprints.some(f => f.fp === fp)) {
    // Already remembered — refresh its timer
    refreshEntry(ebf, wheel, index, fp);
    return;
  }

  // Compute expiry slot
  const ttl = DEFAULT_TTL;  // e.g., 3600 seconds
  const expirySlot = (wheel.currentSlot + Math.ceil(ttl / wheel.slotDuration)) % wheel.slotCount;

  // Insert into EBF
  const fpIndex = ebf.buckets[index].fingerprints.length;
  ebf.buckets[index].fingerprints.push({ fp, wheelSlot: expirySlot, insertedAt: now() });
  ebf.bloomFilter.setBit(index);  // ensure Bloom bit is set

  // Register with timing wheel
  const ref: EBFEntryRef = { bucketIndex: index, fpIndex };
  wheel.slots[expirySlot].add(ref);
}
```

**Refresh (same block requested again before expiry):**

```typescript
function refreshEntry(ebf: EBF, wheel: TimingWheel, bucketIndex: number, fp: number): void {
  const bucket = ebf.buckets[bucketIndex];
  const entry = bucket.fingerprints.find(f => f.fp === fp);
  if (!entry) return;

  // Remove from old wheel slot
  const oldRef: EBFEntryRef = { bucketIndex, fpIndex: bucket.fingerprints.indexOf(entry) };
  wheel.slots[entry.wheelSlot].delete(oldRef);

  // Compute new expiry
  const newSlot = (wheel.currentSlot + Math.ceil(DEFAULT_TTL / wheel.slotDuration)) % wheel.slotCount;
  entry.wheelSlot = newSlot;
  entry.insertedAt = now();

  // Register in new slot
  wheel.slots[newSlot].add(oldRef);
}
```

**Expire (timing wheel advances):**

```typescript
function advanceWheel(ebf: EBF, wheel: TimingWheel): void {
  const now = Date.now();
  const elapsed = now - wheel.lastAdvance;
  const slotsToAdvance = Math.floor(elapsed / (wheel.slotDuration * 1000));

  for (let i = 0; i < slotsToAdvance; i++) {
    wheel.currentSlot = (wheel.currentSlot + 1) % wheel.slotCount;
    const expiredRefs = wheel.slots[wheel.currentSlot];

    for (const ref of expiredRefs) {
      deleteFromEBF(ebf, ref);
    }
    expiredRefs.clear();
  }
  wheel.lastAdvance = now;
}

function deleteFromEBF(ebf: EBF, ref: EBFEntryRef): void {
  const bucket = ebf.buckets[ref.bucketIndex];
  bucket.fingerprints.splice(ref.fpIndex, 1);

  // If bucket is now empty, clear the Bloom filter bit
  if (bucket.fingerprints.length === 0) {
    ebf.bloomFilter.clearBit(ref.bucketIndex);
  }
}
```

**Query (on block acquisition — "do I owe anyone this?"):**

```typescript
function checkRecall(ebf: EBF, blockId: Hash): boolean {
  const { fp, index } = hashToEBF(blockId, ebf.size);

  // Fast path: Bloom filter check
  if (!ebf.bloomFilter.getBit(index)) return false;

  // Slow path: check fingerprints
  return ebf.buckets[index].fingerprints.some(f => f.fp === fp);
}
```

