**On failed Find_Value:**

```c
void remember_failed_request(connection_memory_t* mem, buffer_t* block_hash) {
  uint64_t fp, index;
  hash_to_ebf(block_hash, mem->ebf.size, &fp, &index);

  ebf_bucket_t* bucket = &mem->ebf.buckets[index];

  // Already remembered? Push expiry forward.
  for (size_t i = 0; i < bucket->length; i++) {
    if (bucket->fingerprints[i].fp == fp) {
      move_to_future_slot(mem->wheel, &bucket->fingerprints[i]);
      return;
    }
  }

  // New memory
  uint32_t slot = compute_expiry_slot(mem->wheel, DEFAULT_TTL);
  bucket->fingerprints[bucket->length++] = (timed_fp_t){fp, slot};
  mem->ebf.bloom[fp / 8] |= (1 << (fp % 8));
  mem->wheel.slots[slot].refs[mem->wheel.slots[slot].count++] = 
    (ebf_ref_t){index, bucket->length - 1};
}
```

**On block acquisition (inhale or received push):**

```c
void check_all_memories(node_t* node, buffer_t* block_hash) {
  for (size_t i = 0; i < node->connection_count; i++) {
    connection_memory_t* mem = &node->memories[i];

    if (ebf_query(&mem->ebf, block_hash)) {
      // We owe this peer the block
      push_block(node->connections[i], block_hash, REASON_RECALL);

      // Clear the debt
      ebf_delete(&mem->ebf, block_hash);

      // Strong Hebbian reinforcement
      reinforce_connection(node, node->connections[i], RECALL_WEIGHT_MULTIPLIER);
    }
  }
}
```

**Maintenance tick:**

```c
void memory_tick(node_t* node) {
  uint64_t now = get_time_ms();
  for (size_t i = 0; i < node->connection_count; i++) {
    timing_wheel_t* wheel = &node->memories[i].wheel;
    uint32_t slots_elapsed = (now - wheel->last_tick) / wheel->slot_duration_ms;

    for (uint32_t s = 0; s < slots_elapsed; s++) {
      wheel->current = (wheel->current + 1) % wheel->slot_count;
      slot_t* slot = &wheel->slots[wheel->current];

      for (size_t j = 0; j < slot->count; j++) {
        ebf_delete_ref(&node->memories[i].ebf, &slot->refs[j]);
      }
      slot->count = 0;
    }
    wheel->last_tick = now;
  }
}
```

