### 5. Seek Frequency Throttle

```c
uint64_t seek_interval(float capacity) {
  if (capacity >= 0.50) return UINT64_MAX;  // never seek

  float c = capacity / 0.50;  // normalize to [0, 1]
  float alpha = 2.0;          // quadratic slowdown

  return TAU_MIN + (TAU_MAX - TAU_MIN) * powf(c, alpha);
  // TAU_MIN = 5000ms, TAU_MAX = 300000ms (5 min)
}

bool should_seek(node_t* node) {
  if (node->capacity >= 0.50) return false;
  return (get_time_ms() - node->last_seek) >= seek_interval(node->capacity);
}
```

