      path:     msg.path,
      path_len: msg.path_len,
      latency:  now() - msg.start_time
    })
    msg.replicas_needed--

    // If we still need more replicas, re-emit from here
    if msg.replicas_needed > 0:
      msg.path_len--  // don't double-count self
      FORWARD-STORE(msg)  // continue searching from this node
    return

  // ── 2. TTL EXHAUSTED ──
  if msg.max_hops == 0:
    SEND-STORE-RESPONSE({
      accepted: false,
      replicas_remaining: msg.replicas_needed,
      path: msg.path,
      path_len: msg.path_len
    })
    return

  // ── 3. RECORD SELF ──
  msg.path[msg.path_len++] = self.id
  bloom_insert(msg.visited_bloom, self.id)
  msg.max_hops--

  // ── 4. FORWARD TO SUITABLE CANDIDATES ──
  FORWARD-STORE(msg)


SHOULD-ACCEPT-STORE(self, msg):
  // Already have it?
  if index_peek(self.index, msg.block_hash) != NULL:
    return false

  // Room for it?
  if self.capacity + msg.block_size / self.total_capacity > 1.0:
    return false

  // Am I in exhale phase? Don't accept if I'm about to shed.
  if self.capacity >= 0.80:
    return false

  // Accept with probability proportional to available capacity
  // Fuller nodes are more selective
  float acceptance_prob = 1.0 - (self.capacity / 0.80);
  return random_float() < acceptance_prob;


ACCEPT-STORE(self, msg):
  // Write block to sections
  (section_id, section_index) = sections_write(self.sections, msg.block_data)

  // Create index entry
  entry = index_entry_from(msg.block_hash, section_id, section_index,
                           0, fibonacci_hit_counter_create())
  index_add(self.index, entry)

  // Put into hot cache
  evicted = block_lru_cache_put(self.lru, msg.block_data, entry)
  if evicted != NULL:
    index_set_entry_ejection(self.index, evicted, now())

  // Check EBF memories — do I owe this block to anyone?
  CHECK-ALL-MEMORIES(self, msg.block_hash)


FORWARD-STORE(msg):
  // ── GATHER CANDIDATES ──
  candidates = []

  // Search across multiple rings for diversity
  for ring in [0, 1, 2, 3]:
    for member in ring.members:
      if bloom_contains(msg.visited_bloom, member.id):
        continue   // negative information: already visited

      // Compute composite storage suitability score
      float score = COMPUTE-STORAGE-SCORE(self, member, msg)
      if score > 0.01:
        candidates.push({ id: member.id, score: score })

  if candidates is empty:
    SEND-STORE-RESPONSE({
      accepted: false,
      replicas_remaining: msg.replicas_needed,
      path: msg.path,
      path_len: msg.path_len
    })
    return

  // ── ROULETTE-WHEEL SELECTION ──
  // Weighted by storage suitability score, not pure Hebbian weight
  total_score = sum(c.score for c in candidates)

  fanout = min(FORWARD_FANOUT, msg.replicas_needed * 2)
  for i = 0; i < fanout; i++:
    if candidates is empty: break
    selected = ROULETTE-SELECT(candidates, total_score)
    forward msg to selected
    total_score -= selected.score
    candidates.remove(selected)
```

