typedef struct {
  rpc_header_t  header;
} capacity_query_msg_t;

// Response
typedef struct {
  rpc_header_t  header;
  float         capacity;          // [0.0, 1.0]
  uint8_t       phase;             // INHALE / NEUTRAL / EXHALE
  uint32_t      block_count;       // how many blocks stored
  uint64_t      uptime_seconds;    // how long this node has been up
  uint32_t      free_slots;        // approximate blocks it can still accept
} capacity_response_msg_t;
