## Enforcement on Message Receipt

```c
bool check_rate_limit(node_t* self, node_id_t peer, rpc_type_e type) {
  peer_rate_limits_t* limits = get_or_create_limits(self, peer);
  token_bucket_t* bucket = get_bucket_for_type(limits, type);

  float weight = limits->weight;
  float cap_mult = capacity_multiplier(self->capacity, type);
  float effective_cost = RATE_CONFIGS[type].cost / max(cap_mult, 0.01);

  return token_bucket_consume(bucket, weight, effective_cost);
}

// In the main dispatch loop:
void handle_message(node_t* self, message_t* msg, socket_t* socket) {
  if (!check_rate_limit(self, msg->source, msg->type)) {
    send_rpc(socket, RATE_LIMITED, {
      type:       msg->type,
      retry_after_ms: compute_backoff(msg->source, msg->type),
      current_limit: get_current_limit(msg->source, msg->type)
    });
    return;
  }

  // Proceed with normal handling
  dispatch(self, msg, socket);
}
```

