## Backoff Behavior on RATE_LIMITED

```c
void on_rate_limited(node_t* self, rate_limited_msg_t* msg) {
  node_id_t peer = msg->source;
  rpc_type_e type = msg->type;

  // Exponential backoff per peer+type
  remote_rate_limits_t* remote = get_remote_limits(self, peer);
  uint32_t current_backoff = remote->backoff_duration[type];
  uint32_t new_backoff = min(current_backoff * 2, MAX_BACKOFF_MS);
  if (new_backoff == 0) new_backoff = BACKOFF_BASE_MS;

  remote->backoff_until[type] = now() + new_backoff;
  remote->backoff_duration[type] = new_backoff;

  // Update our view of their limits
  remote->buckets[type].rate = msg->current_limit;
  remote->buckets[type].burst = 0;  // assume depleted

  // For Store: if this was the only candidate, expand ring search
  // For Find_Value: try alternate paths; EBF memory will catch it
}
```

