## 5. Transaction Execution

### 5.1 Execution Pipeline

Every transaction passes through a 12-step pipeline:

```c
exec_result_t execute_transaction(ledger_state_t *state,
                                  const transaction_t *tx) {
    /* Step 1: Prune expired locks */
    prune_expired_locks(state);

    /* Step 2: Verify protocol states */
    for (int i = 0; i < tx->resources_count; i++) {
        resource_state_t current = get_resource_state(state, tx->resources[i]);
        if (current != tx->required_states[i])
            return EXEC_PROTOCOL_VIOLATION;
    }

    /* Step 3: Verify lock claims */
    for (int i = 0; i < tx->lock_claims_count; i++) {
        if (!verify_lock_claim(state, &tx->lock_claims[i]))
            return EXEC_LOCK_MISMATCH;
    }

    /* Step 4: Verify ABE policy */
    if (tx->abe_policy[0] != '\0') {
        if (!am_verify_policy(&state->attr_machine, tx->signer_id,
                              tx->abe_policy))
            return EXEC_UNAUTHORIZED;
    }

    /* Step 5: Verify key is current */
    if (!verify_key_is_current(state, tx->signer_id, tx->key_version))
        return EXEC_KEY_STALE;

    /* Step 6: Verify signature */
    const sig_vtable_t *svt = sig_get_vtable(tx->sig_scheme);
    if (svt->verify(tx->signer_pk, svt->pk_len,
                    (const uint8_t *)tx, sizeof(transaction_t),
                    tx->signature, tx->sig_len) != 0)
        return EXEC_SIG_INVALID;

    /* Step 7: Verify double-entry balance */
    if (tx->debit_amount != tx->credit_amount)
        return EXEC_BALANCE_MISMATCH;

    /* Step 8: Verify sufficient funds */
    if (!check_sufficient_funds(state, tx))
        return EXEC_INSUFFICIENT_FUNDS;

    /* Step 9: Check idempotency (ONE_SHOT_FLAG) */
    if (is_duplicate(state, tx))
        return EXEC_DUPLICATE;

    /* Step 10: Execute SMT updates */
    apply_smt_updates(state, tx);

    /* Step 11: Transition protocol states */
    for (int i = 0; i < tx->resources_count; i++) {
        transition_resource(state, tx->resources[i], tx->next_states[i]);
    }

    /* Step 12: Append to log */
    log_entry_t entry;
    entry.sequence = sequencer_next(&state->sequencer);
    entry.timestamp = tx->timestamp;
    sha256((const uint8_t *)tx, sizeof(transaction_t), entry.tx_hash);
    entry.tx_type = tx->type;
    memcpy(entry.signer_id, tx->signer_id, 32);
    memcpy(entry.smt_root_before, state->smt.root_before_tx, 32);
    memcpy(entry.smt_root_after, state->smt.root, 32);
    txlog_append(&state->tx_log, &entry);

    state->party.state_version++;

    return EXEC_OK;
}
```

### 5.2 Self-Issuance

Self-issuance converts daily credit to real balance:

```c
/*
 * Algorithm: SELF_ISSUE
 *
 * Preconditions:
 *   daily_issuance_used + amount <= SPARKS_PER_DAY - contract_deductions
 *
 * Effect:
 *   daily_issuance.balance  += amount   (tracks usage)
 *   balance.balance         += amount   (real Sparks)
 *   cumulative_debt.balance  += amount  (lifetime debt)
 */

exec_result_t execute_issue(ledger_state_t *state,
                            int64_t amount,
                            const uint8_t signer_id[32]) {
    account_entry_t daily, balance, debt;
    uint8_t k_daily[32], k_balance[32], k_debt[32];

    derive_account_key(k_daily, signer_id, "daily_issuance");
    derive_account_key(k_balance, signer_id, "balance");
    derive_account_key(k_debt, signer_id, "cumulative_debt");

    smt_get(&state->smt, k_daily, &daily);
    smt_get(&state->smt, k_balance, &balance);
    smt_get(&state->smt, k_debt, &debt);

    int64_t deductions = calculate_contract_deductions(state, signer_id);
    int64_t available = SPARKS_PER_DAY - deductions - daily.balance;

    if (amount > available)
        return EXEC_INSUFFICIENT_FUNDS;

    daily.balance   += amount;
    balance.balance += amount;
    debt.balance    += amount;

    daily.nonce++;
    balance.nonce++;
    debt.nonce++;

    smt_set(&state->smt, k_daily, &daily);
    smt_set(&state->smt, k_balance, &balance);
    smt_set(&state->smt, k_debt, &debt);

    return EXEC_OK;
}
```

### 5.3 Cross-Party Payment

Cross-party payments are two separate operations on two separate ledgers, linked by the invoice ID:

```c
/*
 * Algorithm: CROSS_PARTY_PAYMENT
 *
 * Phase 1 (Buyer's ledger): Debit buyer's balance
 * Phase 2 (Seller's ledger): Credit seller's balance (requires attribute)
 *
 * These are asynchronous. The buyer executes Phase 1 first.
 * The seller's ledger verifies the attribute in Phase 2.
 * The invoice state machine links them.
 */

/* Phase 1: Buyer debits their own ledger */
exec_result_t execute_debit_payment(ledger_state_t *buyer_state,
                                    const transaction_t *tx) {
    account_entry_t balance, purchases;
    uint8_t k_bal[32], k_pur[32];

    derive_account_key(k_bal, tx->payer_id, "balance");
    derive_account_key(k_pur, tx->payer_id, "purchases");

    smt_get(&buyer_state->smt, k_bal, &balance);
    smt_get(&buyer_state->smt, k_pur, &purchases);

    /* May need to self-issue first */
    if (balance.balance < tx->amount) {
        int64_t deficit = tx->amount - balance.balance;
        exec_result_t r = execute_issue(buyer_state, deficit, tx->payer_id);
        if (r != EXEC_OK) return r;
        smt_get(&buyer_state->smt, k_bal, &balance);
    }

    balance.balance   -= tx->amount;
    purchases.balance += tx->amount;
    balance.nonce++;
    purchases.nonce++;

    smt_set(&buyer_state->smt, k_bal, &balance);
    smt_set(&buyer_state->smt, k_pur, &purchases);

    return EXEC_OK;
}

/* Phase 2: Seller credits their ledger (requires can_credit attribute) */
exec_result_t execute_credit_payment(ledger_state_t *seller_state,
                                     const transaction_t *tx) {
    /* Verify buyer has the can_credit attribute */
    char attr[96];
    snprintf(attr, sizeof(attr), "can_credit:%s",
            hex_encode(tx->ref_id, 32));

    if (!am_check(&seller_state->attr_machine, tx->payer_id, attr))
        return EXEC_UNAUTHORIZED;

    account_entry_t balance, revenue;
    uint8_t k_bal[32], k_rev[32];

    derive_account_key(k_bal, tx->payee_id, "balance");
    derive_account_key(k_rev, tx->payee_id, "revenue");

    smt_get(&seller_state->smt, k_bal, &balance);
    smt_get(&seller_state->smt, k_rev, &revenue);

    balance.balance += tx->amount;
    revenue.balance += tx->amount;
    balance.nonce++;
    revenue.nonce++;

    smt_set(&seller_state->smt, k_bal, &balance);
    smt_set(&seller_state->smt, k_rev, &revenue);

    /* Revoke the one-time attribute */
    am_revoke(&seller_state->attr_machine, tx->payer_id, attr,
              tx->payee_id, tx->signature);

    /* Transition invoice state */
    invoice_t *inv = find_invoice(seller_state, tx->ref_id);
    invoice_transition(inv, RES_PAID);

    return EXEC_OK;
}
```

