    fprintf(stderr, "Usage: %s --test=<test_name>\n\n", prog);
    fprintf(stderr, "Available tests:\n");
    for (const test_entry_t *t = tests; t->name; t++) {
        fprintf(stderr, "  %-30s %s\n", t->name, t->description);
    }
}

int main(int argc, char **argv) {
    if (argc < 2 || strncmp(argv, "--test=", 7) != 0) {
        print_usage(argv);
        return 1;
    }

    const char *test_name = argv + 7;

    for (const test_entry_t *t = tests; t->name; t++) {
        if (strcmp(t->name, test_name) == 0) {
            int result = t->func();
            if (result == 0) {
                printf("[PASS] %s\n", test_name);
            } else {
                printf("[FAIL] %s (code: %d)\n", test_name, result);
            }
            return result;
        }
    }

    fprintf(stderr, "Unknown test: %s\n", test_name);
    print_usage(argv);
    return 1;
}

/* ================================================================
   Test 1: Basic Setup & Key Generation
   ================================================================ */
static int test_setup_keygen(void) {
    int ret;
    hybrid_abe_ctx_t *ctx = NULL;
    unsigned char *mpk = NULL, *msk = NULL, *key = NULL;
    size_t mpk_len = 0, msk_len = 0, key_len = 0;

    ret = hybrid_abe_global_init();
    if (ret != 0) return ret;

    ret = hybrid_abe_setup(&ctx, &mpk, &mpk_len, &msk, &msk_len);
    if (ret != 0) goto cleanup;
    if (mpk == NULL || mpk_len == 0 || msk == NULL || msk_len == 0) {
        ret = HYBRID_ABE_ERR_INTERNAL;
        goto cleanup;
    }

    ret = hybrid_abe_authority_issue_key(ctx, msk, msk_len, mpk, mpk_len,
                                         "id:alice|role:verified", &key, &key_len);
    if (ret != 0) goto cleanup;
    if (key == NULL || key_len == 0) {
        ret = HYBRID_ABE_ERR_INTERNAL;
        goto cleanup;
    }

    /* Verify attributes are present in the key */
    char *attrs = NULL;
    ret = hybrid_abe_key_get_attributes(ctx, key, key_len, &attrs);
    if (ret != 0) goto cleanup;
    if (strstr(attrs, "id:alice") == NULL || strstr(attrs, "role:verified") == NULL) {
        fprintf(stderr, "Key missing expected attributes. Got: %s\n", attrs);
        hybrid_abe_free_string(attrs);
        ret = HYBRID_ABE_ERR_INTERNAL;
        goto cleanup;
    }
    hybrid_abe_free_string(attrs);

cleanup:
    hybrid_abe_free_buffer(key);
    hybrid_abe_free_buffer(msk);
    hybrid_abe_free_buffer(mpk);
    hybrid_abe_ctx_free(ctx);
    hybrid_abe_global_shutdown();
    return ret;
}

/* ================================================================
   Test 2: User Extends Key & Decrypts
   ================================================================ */
static int test_user_extend_decrypt(void) {
    int ret;
    hybrid_abe_ctx_t *ctx = NULL;
    unsigned char *mpk = NULL, *msk = NULL, *base_key = NULL, *ext_key = NULL;
    unsigned char *ct = NULL, *pt = NULL;
    size_t mpk_len = 0, msk_len = 0, base_key_len = 0, ext_key_len = 0;
    size_t ct_len = 0, pt_len = 0;
    const char *plaintext = "Hello, Hybrid ABE!";

    ret = hybrid_abe_global_init();
    if (ret != 0) return ret;

    ret = hybrid_abe_setup(&ctx, &mpk, &mpk_len, &msk, &msk_len);
    if (ret != 0) goto cleanup;

    /* Authority issues base key */
    ret = hybrid_abe_authority_issue_key(ctx, msk, msk_len, mpk, mpk_len,
                                         "id:alice|role:verified", &base_key, &base_key_len);
    if (ret != 0) goto cleanup;

    /* User extends with self-asserted attributes */
    ret = hybrid_abe_user_extend_key(ctx, mpk, mpk_len, base_key, base_key_len,
                                     "name:Alice_Smith|dept:engineering", &ext_key, &ext_key_len);
    if (ret != 0) goto cleanup;

    /* Encrypt under policy requiring BOTH immutable and user-managed attrs */
    ret = hybrid_abe_encrypt(ctx, mpk, mpk_len,
                             (const unsigned char*)plaintext, strlen(plaintext) + 1,
                             "(id:alice) AND (name:Alice_Smith)",
                             &ct, &ct_len);
    if (ret != 0) goto cleanup;

    /* Decrypt with extended key → should succeed */
    ret = hybrid_abe_decrypt(ctx, ext_key, ext_key_len, ct, ct_len, &pt, &pt_len);
    if (ret != 0) {
        fprintf(stderr, "Decryption with extended key failed\n");
        goto cleanup;
    }
    if (pt_len != strlen(plaintext) + 1 || memcmp(pt, plaintext, pt_len) != 0) {
        fprintf(stderr, "Decrypted plaintext mismatch\n");
        ret = HYBRID_ABE_ERR_INTERNAL;
        goto cleanup;
    }
    hybrid_abe_free_buffer(pt); pt = NULL; pt_len = 0;

    /* Decrypt with BASE key only → should FAIL (missing name:Alice_Smith) */
    ret = hybrid_abe_decrypt(ctx, base_key, base_key_len, ct, ct_len, &pt, &pt_len);
    if (ret == 0) {
        fprintf(stderr, "Base key should NOT have been able to decrypt\n");
        ret = HYBRID_ABE_ERR_INTERNAL;
        goto cleanup;
    }
    /* Expected failure — reset ret */
    ret = 0;

cleanup:
    hybrid_abe_free_buffer(pt);
    hybrid_abe_free_buffer(ct);
    hybrid_abe_free_buffer(ext_key);
    hybrid_abe_free_buffer(base_key);
    hybrid_abe_free_buffer(msk);
    hybrid_abe_free_buffer(mpk);
    hybrid_abe_ctx_free(ctx);
    hybrid_abe_global_shutdown();
    return ret;
}

/* ================================================================
   Test 3: User Updates Self-Asserted Attributes
   ================================================================ */
static int test_user_update_attributes(void) {
    int ret;
    hybrid_abe_ctx_t *ctx = NULL;
    unsigned char *mpk = NULL, *msk = NULL, *base_key = NULL;
    unsigned char *ext_key1 = NULL, *ext_key2 = NULL;
    unsigned char *ct = NULL, *pt = NULL;
    size_t mpk_len = 0, msk_len = 0, base_key_len = 0;
    size_t ext_key1_len = 0, ext_key2_len = 0;
    size_t ct_len = 0, pt_len = 0;
    const char *plaintext = "Attribute update test";

    ret = hybrid_abe_global_init();
    if (ret != 0) return ret;

    ret = hybrid_abe_setup(&ctx, &mpk, &mpk_len, &msk, &msk_len);
    if (ret != 0) goto cleanup;

    ret = hybrid_abe_authority_issue_key(ctx, msk, msk_len, mpk, mpk_len,
                                         "id:alice", &base_key, &base_key_len);
    if (ret != 0) goto cleanup;

    /* First extension: name:Alice_Smith */
    ret = hybrid_abe_user_extend_key(ctx, mpk, mpk_len, base_key, base_key_len,
                                     "name:Alice_Smith", &ext_key1, &ext_key1_len);
    if (ret != 0) goto cleanup;

    /* Encrypt under policy with old name */
    ret = hybrid_abe_encrypt(ctx, mpk, mpk_len,
                             (const unsigned char*)plaintext, strlen(plaintext) + 1,
                             "(id:alice) AND (name:Alice_Smith)",
                             &ct, &ct_len);
    if (ret != 0) goto cleanup;

    /* Decrypt with ext_key1 → succeeds */
    ret = hybrid_abe_decrypt(ctx, ext_key1, ext_key1_len, ct, ct_len, &pt, &pt_len);
    if (ret != 0) {
        fprintf(stderr, "Decrypt with first extension failed\n");
        goto cleanup;
    }
    hybrid_abe_free_buffer(pt); pt = NULL; pt_len = 0;
    hybrid_abe_free_buffer(ct); ct = NULL; ct_len = 0;

    /* User changes name: re-delegate from base with new attribute */
    ret = hybrid_abe_user_update_attributes(ctx, mpk, mpk_len, base_key, base_key_len,
                                            "name:A_Smith", &ext_key2, &ext_key2_len);
    if (ret != 0) goto cleanup;

    /* Encrypt under policy with NEW name */
    ret = hybrid_abe_encrypt(ctx, mpk, mpk_len,
                             (const unsigned char*)plaintext, strlen(plaintext) + 1,
                             "(id:alice) AND (name:A_Smith)",
                             &ct, &ct_len);
    if (ret != 0) goto cleanup;

    /* Decrypt with ext_key2 → succeeds */
    ret = hybrid_abe_decrypt(ctx, ext_key2, ext_key2_len, ct, ct_len, &pt, &pt_len);
    if (ret != 0) {
        fprintf(stderr, "Decrypt with updated extension failed\n");
        goto cleanup;
    }

    /* Old ext_key1 should NOT work with new ciphertext */
    hybrid_abe_free_buffer(pt); pt = NULL; pt_len = 0;
    ret = hybrid_abe_decrypt(ctx, ext_key1, ext_key1_len, ct, ct_len, &pt, &pt_len);
    if (ret == 0) {
        fprintf(stderr, "Old key should NOT decrypt new ciphertext\n");
        ret = HYBRID_ABE_ERR_INTERNAL;
        goto cleanup;
    }
    ret = 0;

cleanup:
    hybrid_abe_free_buffer(pt);
    hybrid_abe_free_buffer(ct);
    hybrid_abe_free_buffer(ext_key2);
    hybrid_abe_free_buffer(ext_key1);
    hybrid_abe_free_buffer(base_key);
    hybrid_abe_free_buffer(msk);
    hybrid_abe_free_buffer(mpk);
    hybrid_abe_ctx_free(ctx);
    hybrid_abe_global_shutdown();
    return ret;
}

