static int test_collusion_resistance(void) {
    int ret;
    hybrid_abe_ctx_t *ctx = NULL;
    unsigned char *mpk = NULL, *msk = NULL;
    unsigned char *alice_base = NULL, *bob_base = NULL;
    unsigned char *alice_ext = NULL, *bob_ext = NULL;
    unsigned char *ct = NULL, *pt = NULL;
    size_t mpk_len = 0, msk_len = 0;
    size_t alice_base_len = 0, bob_base_len = 0;
    size_t alice_ext_len = 0, bob_ext_len = 0;
