    if (ret != 0) return ret;

    ret = hybrid_abe_setup(&ctx, &mpk, &mpk_len, &msk, &msk_len);
    if (ret != 0) goto cleanup;

    /* Issue keys for Alice and Bob */
    ret = hybrid_abe_authority_issue_key(ctx, msk, msk_len, mpk, mpk_len,
                                         "id:alice", &alice_base, &alice_base_len);
    if (ret != 0) goto cleanup;

    ret = hybrid_abe_authority_issue_key(ctx, msk, msk_len, mpk, mpk_len,
                                         "id:bob", &bob_base, &bob_base_len);
    if (ret != 0) goto cleanup;

    /* Alice extends with dept:engineering */
    ret = hybrid_abe_user_extend_key(ctx, mpk, mpk_len, alice_base, alice_base_len,
                                     "dept:engineering", &alice_ext, &alice_ext_len);
    if (ret != 0) goto cleanup;

    /* Bob extends with role:manager */
    ret = hybrid_abe_user_extend_key(ctx, mpk, mpk_len, bob_base, bob_base_len,
                                     "role:manager", &bob_ext, &bob_ext_len);
    if (ret != 0) goto cleanup;

    /* Encrypt under policy that only Alice should satisfy */
    ret = hybrid_abe_encrypt(ctx, mpk, mpk_len,
                             (const unsigned char*)plaintext, strlen(plaintext) + 1,
                             "(id:alice) AND (dept:engineering)",
