    /* Bob decrypts → should FAIL (Bob has id:bob, not id:alice) */
    ret = hybrid_abe_decrypt(ctx, bob_ext, bob_ext_len, ct, ct_len, &pt, &pt_len);
    if (ret == 0) {
        fprintf(stderr, "Bob should NOT be able to decrypt Alice's ciphertext\n");
        ret = HYBRID_ABE_ERR_INTERNAL;
        goto cleanup;
