    ret = 0;

cleanup:
    hybrid_abe_free_buffer(pt);
    hybrid_abe_free_buffer(ct);
    hybrid_abe_free_buffer(bob_ext);
    hybrid_abe_free_buffer(alice_ext);
    hybrid_abe_free_buffer(bob_base);
