## Phase 2: Core Data Structures 📦

### `include/crable_types.h`

```c
#ifndef CRABLE_TYPES_H
#define CRABLE_TYPES_H

#include <stdint.h>
#include <stddef.h>

/* === Cryptographic Constants === */
#define CRABLE_HASH_SIZE        32  /* SHA-256 */
#define CRABLE_SIG_SIZE         64  /* ECDSA secp256k1 */
#define CRABLE_MAX_ATTRS        64
#define CRABLE_MAX_POLICIES     32
#define CRABLE_MAX_USERS        128
#define CRABLE_MAX_LOG_ENTRIES  1024

/* === User === */
typedef struct {
    char     user_id[64];
    size_t   attr_count;
    char     attr_names[CRABLE_MAX_ATTRS][32];
    char     attr_values[CRABLE_MAX_ATTRS][64];

    /* Cryptographic material (private — never exposed) */
    uint8_t  *sk_abe;           /* ABE secret key */
    size_t    sk_abe_len;
    uint8_t   sk_ecdsa[32];     /* ECDSA private key */

    /* Public verification key */
    uint8_t   pk_ecdsa[33];     /* Compressed ECDSA public key */
} crable_user_t;

/* === Capability Vault Entry === */
typedef struct {
    char     operation[32];
    char     user_id[64];
    uint8_t  *encrypted_sk_share;  /* ABE ciphertext of ECDSA key */
    size_t    encrypted_len;
} crable_vault_entry_t;

/* === Policy === */
typedef struct {
    char     operation[32];
    char     expression[256];    /* e.g., "role:writer OR role:admin" */
} crable_policy_t;

/* === Transition Message === */
typedef struct {
    char     operation[32];
    uint8_t  old_state_hash[CRABLE_HASH_SIZE];
    uint8_t  new_data_hash[CRABLE_HASH_SIZE];
    uint64_t timestamp;
    uint64_t nonce;
} crable_transition_msg_t;

/* === Transition Request === */
typedef struct {
    crable_transition_msg_t message;
    char     signer_id[64];      /* Empty string = privacy mode */
    uint8_t  signature[CRABLE_SIG_SIZE];
} crable_transition_request_t;

/* === Transition Log Entry === */
typedef struct {
    uint64_t version;
    crable_transition_request_t request;
    char     verified_signer[64]; /* Filled in by verifier */
    uint8_t  new_state_hash[CRABLE_HASH_SIZE];
} crable_log_entry_t;

/* === State Machine === */
typedef struct {
    uint64_t version;
    uint8_t  *data;              /* Application data (opaque blob) */
    size_t    data_len;

    size_t    policy_count;
    crable_policy_t policies[CRABLE_MAX_POLICIES];

    size_t    log_count;
    crable_log_entry_t log[CRABLE_MAX_LOG_ENTRIES];

    /* Internal — not serialized */
    struct crable_ctx *ctx;
} crable_state_t;

#endif /* CRABLE_TYPES_H */
```

