## Phase 3: Public API 🚪

### `include/crable.h`

```c
#ifndef CRABLE_H
#define CRABLE_H

#include "crable_types.h"
#include "crable_errors.h"

/* === Lifecycle === */

/* Initialize the library. Call once at process start. */
int crable_global_init(void);

/* Shutdown the library. Call once at process exit. */
void crable_global_shutdown(void);

/* === Authority Operations === */

/* Create a new state machine instance.
   Generates MPK, MSK, and the state machine's ECDSA keypair. */
int crable_setup(
    crable_state_t **state_out,
    uint8_t **mpk_out, size_t *mpk_len_out,
    uint8_t **msk_out, size_t *msk_len_out
);

/* Register a user with the authority.
   Generates ABE key + ECDSA keypair for the user.
   Attributes are pipe-separated: "role:writer|dept:engineering" */
int crable_register_user(
    const uint8_t *msk, size_t msk_len,
    const uint8_t *mpk, size_t mpk_len,
    const char *user_id,
    const char *attr_string,
    uint8_t **sk_abe_out, size_t *sk_abe_len_out,
    uint8_t *sk_ecdsa_out,    /* 32 bytes */
    uint8_t *pk_ecdsa_out     /* 33 bytes */
);

/* Populate the capability vault.
   For each operation in the state's policies, encrypt each
   authorized user's ECDSA signing key under "user_id:<id>". */
int crable_vault_populate(
    crable_state_t *state,
    const uint8_t *mpk, size_t mpk_len,
    const crable_user_t *users, size_t user_count
);

/* === User Operations === */

/* User creates a transition request.
   Decrypts their signing key from the vault, then signs the message.
   Set signer_id to "" for privacy mode (Mode B). */
int crable_create_transition(
    const crable_state_t *state,
    const char *operation,
    const uint8_t *new_data, size_t new_data_len,
    const uint8_t *sk_abe, size_t sk_abe_len,
    const uint8_t *sk_ecdsa,
    const char *signer_id,
    crable_transition_request_t *request_out
);

/* === State Machine Operations === */

/* Apply a transition request to the state.
   Verifies the signature against all users authorized by the policy.
   Updates state, logs the transition, and handles policy changes. */
int crable_apply_transition(
    crable_state_t *state,
    const crable_transition_request_t *request,
    const uint8_t *mpk, size_t mpk_len,
    const crable_user_t *users, size_t user_count,
    const uint8_t *vault, size_t vault_len
);

/* === Utility === */

/* Serialize/deserialize state to/from a byte buffer. */
int crable_state_serialize(
    const crable_state_t *state,
    uint8_t **buf_out, size_t *len_out
);
int crable_state_deserialize(
    const uint8_t *buf, size_t len,
    crable_state_t *state_out
);

/* Free allocated memory. */
void crable_free_buffer(uint8_t *buf);
void crable_state_free(crable_state_t *state);

#endif /* CRABLE_H */
```

