    state->policy_count = 5;
    strcpy(state->policies[0].operation, "edit");
    strcpy(state->policies[0].expression, "role:author");
    strcpy(state->policies[1].operation, "submit");
    strcpy(state->policies[1].expression, "role:author");
    // ... review, approve, publish ...

    // 3. Register users
    uint8_t alice_sk_abe[1024]; size_t alice_sk_len;
    uint8_t alice_sk_ecdsa[32], alice_pk_ecdsa[33];
    crable_register_user(msk, msk_len, mpk, mpk_len,
                         "alice", "role:author|dept:engineering",
                         &alice_sk_abe, &alice_sk_len,
                         alice_sk_ecdsa, alice_pk_ecdsa);

    // ... register bob (reviewer), carol (editor), dave (admin) ...

    // 4. Populate vault
    crable_user_t users[4] = { ... };
    crable_vault_populate(state, mpk, mpk_len, users, 4);

    // 5. Alice edits the document
    crable_transition_request_t req;
    crable_create_transition(state, "edit", 
                             "Q4 Report v1", 13,
                             alice_sk_abe, alice_sk_len,
                             alice_sk_ecdsa, "alice", &req);

    // 6. State machine applies the transition
    crable_apply_transition(state, &req, mpk, mpk_len, users, 4, ...);
