## Data Type System 📦

### Built-in Types

```c
typedef enum {
    CRABS_TYPE_COUNTER,      // G-Counter (grow only)
    CRABS_TYPE_PN_COUNTER,   // PN-Counter (positive/negative)
    CRABS_TYPE_SET,          // OR-Set (observed-remove)
    CRABS_TYPE_2P_SET,       // Two-phase set (add then remove)
    CRABS_TYPE_REGISTER,     // LWW-Register (last-writer-wins)
    CRABS_TYPE_DOCUMENT,     // RGA (replicated growable array)
    CRABS_TYPE_RESOURCE,     // Scarcity item (requires locking)
    CRABS_TYPE_CUSTOM        // User-defined (callback)
} crabs_data_type_t;
```

### Type Definition

```c
typedef struct {
    crabs_data_type_t type;
    char name[64];

    /* Invariants — checked AFTER every operation */
    size_t invariant_count;
    crabs_invariant_t invariants[8];

    /* Lock requirement */
    bool requires_lock;  // true for RESOURCE, false for others

    /* CRDT merge strategy */
    crabs_merge_strategy_t merge;

    /* Custom type callbacks (for CRABS_TYPE_CUSTOM) */
    int (*validate)(const uint8_t *data, size_t len);
    int (*merge)(uint8_t *a, size_t *a_len, const uint8_t *b, size_t b_len);
} crabs_type_def_t;
```

### Invariants

```c
typedef struct {
    enum {
        CRABS_INV_GREATER_THAN,      // value > X
        CRABS_INV_LESS_THAN,         // value < X
        CRABS_INV_EQUAL_TO,          // value == X
        CRABS_INV_NOT_EQUAL,         // value != X
        CRABS_INV_DIVISIBLE_BY,      // value % X == 0
        CRABS_INV_UNIQUE,            // no duplicates in set
        CRABS_INV_SUBSET_OF,         // all values must be in another set
        CRABS_INV_CUSTOM             // user-defined callback
    } type;

    union {
        int64_t int_value;
        char string_value[64];
        bool (*custom_check)(const uint8_t *data, size_t len);
    };

    char error_message[128];  // Shown when invariant fails
} crabs_invariant_t;
```

