## How It Works: The Flow

### 1. Define Data Types

```c
// Setup phase — define the shape of the state

crabs_define_type(state, "treasury", CRABS_TYPE_RESOURCE, 
                  .invariants = {
                      {CRABS_INV_GREATER_THAN, .int_value = 0, 
                       .error_message = "Treasury cannot go negative"}
                  },
                  .requires_lock = true);

crabs_define_type(state, "members", CRABS_TYPE_SET,
                  .invariants = {
                      {CRABS_INV_UNIQUE, 
                       .error_message = "Duplicate members not allowed"}
                  },
                  .requires_lock = false);

crabs_define_type(state, "seats", CRABS_TYPE_RESOURCE,
                  .invariants = {
                      {CRABS_INV_GREATER_THAN, .int_value = 0,
                       .error_message = "Seats cannot be negative"},
                      {CRABS_INV_DIVISIBLE_BY, .int_value = 2,
                       .error_message = "Seats must be allocated in pairs"}
                  },
                  .requires_lock = true);
```

### 2. Define Operations (Arbitrary)

```c
// Operations are just data — the state machine doesn't interpret them

// Example: "transfer" operation
crabs_operation_t op = {
    .type = "transfer",
    .payload = "{ \"from\": \"treasury\", \"to\": \"bob\", \"amount\": 10 }",
    .reads = {"treasury"},
    .writes = {"treasury"},
    .lock_claims = {
        {.resource = "treasury", .lock_token = {0xA3, 0xF7, ...}}
    },
    .policy = "role:admin",
    .signature = {0x...},
    .signer_id = "carol",
    .lamport_time = 2042
};
```

### 3. State Machine Applies It

```c
int crabs_apply_operation(crabs_state_t *state, crabs_operation_t *op) {
    // Step 1: Verify signature against policy
    // (ABE-gated ECDSA check)

    // Step 2: Verify lock claims
    for each claim in op.lock_claims:
        if not crabs_verify_lock(state, claim.resource, claim.lock_token):
            return CRABS_ERR_LOCK_MISMATCH;

    // Step 3: Read current values of touched data items
    snapshot = crabs_read_snapshot(state, op.reads);

    // Step 4: Call the operation handler (user-provided)
    // The handler receives the snapshot and returns new values
    result = op_handler(op.type, snapshot, op.payload);
    // Handler is a callback registered by the application

    // Step 5: Verify invariants on ALL written items
    for each write in op.writes:
        new_value = result.writes[write];
        type = state->types[write];
        if not crabs_check_invariants(type, new_value):
            return CRABS_ERR_INVARIANT_VIOLATED;

    // Step 6: Apply CRDT merge
    for each write in op.writes:
        crabs_crdt_merge(state, write, result.writes[write]);

    // Step 7: Log
    crabs_log_operation(state, op);

    return CRABS_SUCCESS;
}
```

