        {"idle",     "__lock__",    "locked"},
        {"locked",   "transfer",    "modified"},
        {"locked",   "withdraw",    "modified"},
        {"locked",   "deposit",     "modified"},
        {"modified", "__verify__",  "verified"},
        {"modified", "__rollback__","idle"},
