```c
int crabs_check_protocol(crabs_state_t *state, crabs_operation_t *op) {
    for (int i = 0; i < op->resource_count; i++) {
        const char *res_name = op->resources[i];
        crabs_resource_t *res = crabs_get_resource(state, res_name);

        // Check current state matches required state
        if (strcmp(res->protocol_state, op->required_state[i]) != 0) {
            return CRABS_ERR_PROTOCOL_VIOLATION;
            // "treasury is in state 'idle', but operation requires 'locked'"
        }

        // Check lock ownership (if resource is locked)
        if (res->protocol_state == CRABS_STATE_LOCKED) {
            if (!crabs_verify_lock_token(res, op->lock_token)) {
                return CRABS_ERR_LOCK_MISMATCH;
            }
        }
    }

    return CRABS_SUCCESS;
}
