## The Lock Manager: Atomic Acquisition

```c
typedef struct {
    char resource[64];
    uint8_t lock_token[32];
    uint64_t expiry;
    char owner_id[64];
    bool acquired;
} crabs_lock_claim_t;

int crabs_lock_acquire_atomic(crabs_state_t *state, 
                               crabs_lock_claim_t *claims,
                               size_t claim_count) {

    // Phase 1: Attempt to acquire ALL locks
    for (int i = 0; i < claim_count; i++) {
        crabs_resource_t *res = crabs_get_resource(state, claims[i].resource);

        if (res->protocol_state != CRABS_STATE_IDLE) {
            // Resource is locked by someone else
            // RELEASE ALL acquired locks so far (Phase 1b)
            for (int j = 0; j < i; j++) {
                crabs_lock_release(state, claims[j].resource);
            }
            return CRABS_ERR_LOCK_CONTENTION;
        }

        // Acquire this lock
        res->protocol_state = CRABS_STATE_LOCKED;
        memcpy(res->lock_token, claims[i].lock_token, 32);
        res->lock_expiry = now() + LOCK_TIMEOUT_MS;
        claims[i].acquired = true;
    }

    // Phase 2: All locks acquired — operation can proceed
    return CRABS_SUCCESS;
}
```

