## The Atomic Lock Primitive (Formalized)

```c
/* 
 * __lock__ primitive
 * 
 * Input:  array of {resource_name, lock_token}
 * Output: success if ALL acquired, failure if ANY cannot
 * 
 * Atomicity guarantee:
 *   If any resource cannot be locked, ALL are released.
 *   No partial lock state is ever visible.
 */

int crabs_primitive_lock(crabs_state_t *state, crabs_operation_t *op) {
    // Temporary storage for acquired locks
    crabs_lock_claim_t acquired[CRABS_MAX_RESOURCES];
    int acquired_count = 0;

    // Phase 1: Attempt all
    for (int i = 0; i < op->resource_count; i++) {
        const char *res_name = op->resources[i];
        crabs_resource_t *res = crabs_get_resource(state, res_name);

        // Check resource exists
        if (!res) return CRABS_ERR_RESOURCE_NOT_FOUND;

        // Check resource is in "idle" state
        if (res->protocol_state != CRABS_STATE_IDLE) {
            // Resource is locked or in an invalid state
            goto rollback;
        }

        // Check the caller's policy allows locking this resource
        if (!crabs_check_policy(state, op->policy, op->signer_id)) {
            goto rollback;
        }

        // Acquire
        res->protocol_state = CRABS_STATE_LOCKED;
        memcpy(res->lock_token, op->lock_claims[i].lock_token, 32);
        res->lock_owner = op->signer_id;
        res->lock_expiry = crabs_now() + CRABS_LOCK_TIMEOUT_MS;
        res->pre_lock_snapshot = crabs_snapshot_resource(res);

        acquired[acquired_count++] = op->lock_claims[i];
    }

    return CRABS_SUCCESS;

rollback:
    // Release everything we acquired
    for (int j = 0; j < acquired_count; j++) {
        crabs_resource_t *res = crabs_get_resource(state, acquired[j].resource);
        res->protocol_state = CRABS_STATE_IDLE;
        memset(res->lock_token, 0, 32);
        res->lock_owner[0] = '\0';
        crabs_free_snapshot(res->pre_lock_snapshot);
        res->pre_lock_snapshot = NULL;
    }

    return CRABS_ERR_LOCK_CONTENTION;
}
```

