## The Operation Execution (With Multi-Resource Verification)

```c
int crabs_execute_operation(crabs_state_t *state, crabs_operation_t *op) {

    // Step 1: Verify ALL resources are locked with matching tokens
    for (int i = 0; i < op->resource_count; i++) {
        crabs_resource_t *res = crabs_get_resource(state, op->resources[i]);

        if (res->protocol_state != CRABS_STATE_LOCKED) {
            return CRABS_ERR_NOT_LOCKED;
        }

        if (memcmp(res->lock_token, op->lock_claims[i].lock_token, 32) != 0) {
            return CRABS_ERR_LOCK_TOKEN_MISMATCH;
        }

        if (strcmp(res->lock_owner, op->signer_id) != 0 && 
            strlen(op->signer_id) > 0) {
            return CRABS_ERR_LOCK_OWNER_MISMATCH;
        }
    }

    // Step 2: Verify protocol state transitions are valid
    for (int i = 0; i < op->resource_count; i++) {
        if (!crabs_check_transition(state, op->resources[i], 
                                     op->required_state[i],
                                     op->next_state[i])) {
            return CRABS_ERR_PROTOCOL_VIOLATION;
        }
    }

    // Step 3: Verify ABE policy
    if (!crabs_verify_signature(state, op)) {
        return CRABS_ERR_UNAUTHORIZED;
    }

    // Step 4: Execute the operation handler
    int result = op->handler(state, op);
    if (result != CRABS_SUCCESS) {
        return result;
    }

    // Step 5: Transition ALL resources to next state
    for (int i = 0; i < op->resource_count; i++) {
        crabs_resource_t *res = crabs_get_resource(state, op->resources[i]);
        res->protocol_state = op->next_state[i];
    }

    // Step 6: Log
    crabs_log_operation(state, op);

    return CRABS_SUCCESS;
}
```

