## The Force-Unlock Primitive

```c
/*
 * __force_unlock__ primitive
 *
 * Anyone can call this on an EXPIRED lock.
 * It rolls back the resource to its pre-lock state
 * and transitions it back to "idle".
 *
 * This is a SAFETY valve — not a normal operation.
 */

int crabs_primitive_force_unlock(crabs_state_t *state, 
                                  const char *resource,
                                  const char *requester_id) {

    crabs_resource_t *res = crabs_get_resource(state, resource);

    // Step 1: Verify lock is actually expired
    if (crabs_now() < res->lock_expiry) {
        return CRABS_ERR_LOCK_NOT_EXPIRED;
        // "Lock on treasury has not expired yet. 
        //  Expires in 3 seconds."
    }

    // Step 2: Verify the state machine allows force-unlock
    if (!state->config.lock.allow_force_unlock) {
        return CRABS_ERR_FORCE_UNLOCK_DISABLED;
    }

    // Step 3: Roll back to pre-lock snapshot
    if (res->pre_lock_snapshot != NULL) {
        crabs_restore_snapshot(res, res->pre_lock_snapshot);
        crabs_free_snapshot(res->pre_lock_snapshot);
        res->pre_lock_snapshot = NULL;
    }

    // Step 4: Release the lock
    res->protocol_state = CRABS_STATE_IDLE;
    memset(res->lock_token, 0, 32);
    res->lock_owner[0] = '\0';
    res->lock_expiry = 0;

    // Step 5: Log the force-unlock
    crabs_log_entry_t log_entry = {
        .version = state->version++,
        .operation_type = "__force_unlock__",
        .resource = resource,
        .forced_by = requester_id,
        .previous_owner = res->lock_owner,  // Who lost the lock
        .timestamp = crabs_now(),
        .reason = "Lock expired"
    };
    crabs_append_log(state, &log_entry);

    return CRABS_SUCCESS;
}
```

