## The Timeout Check: Integrated Into Every Operation

```c
int crabs_check_lock_expiry(crabs_state_t *state) {
    uint64_t now = crabs_now();
    bool force_unlocked_any = false;

    for (int i = 0; i < state->lock_manager.lock_count; i++) {
        crabs_lock_t *lock = &state->lock_manager.locks[i];

        if (lock->protocol_state != CRABS_STATE_IDLE && 
            now >= lock->expires_at) {

            // Auto force-unlock — no one needs to request it
            crabs_primitive_force_unlock(state, 
                                          lock->resource_name,
                                          "__system__");  // System-initiated

            force_unlocked_any = true;
        }
    }

    return force_unlocked_any ? CRABS_LOCK_EXPIRED : CRABS_SUCCESS;
}

// Called at the start of EVERY operation
int crabs_begin_operation(crabs_state_t *state, crabs_operation_t *op) {
    // Prune expired locks first
    crabs_check_lock_expiry(state);

    // Then proceed with normal operation logic
    // ...
}
