## The Solution: Abstract Signature Layer

### 1. Signature Scheme Registry

```c
// Each supported scheme gets a unique ID
typedef enum {
    CRABS_SIG_ECDSA_SECP256K1   = 0x01,  // ECDSA with secp256k1
    CRABS_SIG_ECDSA_P256        = 0x02,  // ECDSA with P-256
    CRABS_SIG_ED25519           = 0x03,  // Ed25519
    CRABS_SIG_RSA_2048          = 0x04,  // RSA 2048-bit
    CRABS_SIG_RSA_4096          = 0x05,  // RSA 4096-bit
    CRABS_SIG_SCHNORR_SECP256K1 = 0x06,  // Schnorr over secp256k1
    CRABS_SIG_BLS_BLS12_381     = 0x07,  // BLS over BLS12-381
    CRABS_SIG_DILITHIUM_2       = 0x08,  // NIST post-quantum Level 2
    CRABS_SIG_DILITHIUM_3       = 0x09,  // NIST post-quantum Level 3
    CRABS_SIG_DILITHIUM_5       = 0x0A,  // NIST post-quantum Level 5
    CRABS_SIG_FALCON_512        = 0x0B,  // NIST post-quantum alternative
    CRABS_SIG_CUSTOM            = 0xFF   // Application-defined
} crabs_sig_scheme_t;
```

### 2. Virtual Table for Signature Operations

```c
// Every signature scheme implements this interface
typedef struct {
    crabs_sig_scheme_t scheme_id;
    const char *name;              // "ECDSA-secp256k1"

    // Key sizes
    size_t public_key_size;        // 33 for secp256k1 compressed
    size_t secret_key_size;        // 32 for secp256k1
    size_t signature_size;         // 64 for secp256k1

    // Key generation
    int (*generate_keypair)(uint8_t *pk, size_t *pk_len,
                            uint8_t *sk, size_t *sk_len);

    // Signing
    int (*sign)(const uint8_t *sk, size_t sk_len,
                const uint8_t *msg, size_t msg_len,
                uint8_t *sig, size_t *sig_len);

    // Verification
    int (*verify)(const uint8_t *pk, size_t pk_len,
                  const uint8_t *msg, size_t msg_len,
                  const uint8_t *sig, size_t sig_len);

    // Serialization
    int (*export_key)(const uint8_t *key, size_t key_len,
                      uint8_t *buf, size_t *buf_len);
    int (*import_key)(const uint8_t *buf, size_t buf_len,
                      uint8_t *key, size_t *key_len);

    // Optional: batch verification
    int (*verify_batch)(const uint8_t **pks, const size_t *pk_lens,
                        const uint8_t **msgs, const size_t *msg_lens,
                        const uint8_t **sigs, const size_t *sig_lens,
                        size_t count);

} crabs_sig_vtable_t;
```

