## The VTable Registry

```c
// Global registry of supported signature schemes
static crabs_sig_vtable_t *sig_registry[256];

// Register a scheme at startup
int crabs_register_sig_scheme(crabs_sig_vtable_t *vtable) {
    if (sig_registry[vtable->scheme_id] != NULL) {
        return CRABS_ERR_SCHEME_EXISTS;  // Already registered
    }
    sig_registry[vtable->scheme_id] = vtable;
    return CRABS_SUCCESS;
}

// Get the vtable for a scheme
crabs_sig_vtable_t *crabs_get_sig_vtable(crabs_sig_scheme_t scheme) {
    return sig_registry[scheme];
}

// Built-in schemes are registered at init
int crabs_global_init(void) {
    // ... existing init ...

    crabs_register_sig_scheme(&crabs_ecdsa_secp256k1_vtable);
    crabs_register_sig_scheme(&crabs_ed25519_vtable);
    crabs_register_sig_scheme(&crabs_rsa_2048_vtable);

    #ifdef CRABS_ENABLE_DILITHIUM
        crabs_register_sig_scheme(&crabs_dilithium_2_vtable);
    #endif

    return CRABS_SUCCESS;
}
