## Implementation

### 1. Define AIDL Interfaces

**IPubSubService.aidl** (hosted by daemon):
```java
package com.yourdaemon;

import com.yourdaemon.IPubSubClient;

interface IPubSubService {
    void subscribe(String topic, IPubSubClient callback);
    void unsubscribe(String topic, IPubSubClient callback);
    void publish(String topic, in Bundle message);
    List<String> getTopics();
}
```

**IPubSubClient.aidl** (callback to client):
```java
package com.yourdaemon;

interface IPubSubClient {
    void onMessage(String topic, in Bundle message);
    String getClientId();
}
```

### 2. Daemon Service (Kotlin)

```kotlin
class PubSubDaemonService : Service() {

    private val subscriptions = ConcurrentHashMap<String, MutableList<IPubSubClient>>()
    private val messageQueue = LinkedBlockingQueue<Message>()
    private val dispatcherThread = Executors.newSingleThreadExecutor()

    private val binder = object : IPubSubService.Stub() {
        override fun subscribe(topic: String, callback: IPubSubClient?) {
            callback?.let { 
                subscriptions.computeIfAbsent(topic) { CopyOnWriteArrayList() }.add(it)
                linkToDeath(callback) // Critical: detect client death
            }
        }

        override fun unsubscribe(topic: String, callback: IPubSubClient?) {
            subscriptions[topic]?.remove(callback)
        }

        override fun publish(topic: String, message: Bundle?) {
            messageQueue.offer(Message(topic, message))
        }

        override fun getTopics(): List<String> = subscriptions.keys.toList()
    }

    override fun onCreate() {
        super.onCreate()
        startForeground(1, createNotification())

        // Message dispatcher
        dispatcherThread.execute {
            while (!Thread.currentThread().isInterrupted) {
                val msg = messageQueue.take()
                dispatch(msg)
            }
        }
    }

    private fun dispatch(msg: Message) {
        val clients = subscriptions[msg.topic] ?: return
        clients.forEach { client ->
            try {
                client.onMessage(msg.topic, msg.data)
            } catch (e: DeadObjectException) {
                // Client died, clean up
                subscriptions[msg.topic]?.remove(client)
            }
        }
    }

    private fun linkToDeath(callback: IPubSubClient) {
        callback.asBinder().linkToDeath({
            // Remove dead client from all topics
            subscriptions.values.forEach { it.remove(callback) }
        }, 0)
    }

    override fun onBind(intent: Intent): IBinder = binder

    data class Message(val topic: String, val data: Bundle?)
}
```

