## Architecture: Native Binder Service

### C++ Service Implementation (Native Daemon)

```cpp
// IPubSubService.h (Interface Token)
#define PUBSUB_SERVICE_NAME "com.yourdaemon.pubsub"

// Native Service Implementation
#include <binder/BinderService.h>
#include <binder/IInterface.h>
#include <binder/Parcel.h>

class PubSubService : public BBinder {
public:
    PubSubService() {}

    virtual status_t onTransact(
        uint32_t code, 
        const Parcel& data, 
        Parcel* reply,
        uint32_t flags = 0) {

        // Security: Check caller UID
        uid_t uid = IPCThreadState::self()->getCallingUid();
        if (!isAuthorized(uid)) {
            return PERMISSION_DENIED;
        }

        switch(code) {
            case PUBLISH: {
                String16 topic;
                data.readString16(&topic);
                // Process message...
                reply->writeInt32(NO_ERROR);
                return NO_ERROR;
            }
            case SUBSCRIBE: {
                sp<IBinder> client = data.readStrongBinder();
                registerClient(client, topic);
                return NO_ERROR;
            }
        }
        return BBinder::onTransact(code, data, reply, flags);
    }
};
```

