### 2. Client SDK (AAR Library)

Distribute this to app developers:

```java
public class PubSubClient {
    private static final String SERVICE_PACKAGE = "com.yourcompany.pubsub-daemon";
    private static final String SERVICE_ACTION = "com.yourcompany.pubsub.IPubSubService";

    private final Context context;
    private IPubSubService service;

    public PubSubClient(Context context) {
        this.context = context.getApplicationContext();
    }

    /**
     * Checks if daemon is installed. If not, opens Play Store.
     * Returns true if ready to connect.
     */
    public boolean ensureInstalled() {
        if (isServiceInstalled()) {
            return true;
        }

        // Redirect to Play Store
        try {
            context.startActivity(new Intent(Intent.ACTION_VIEW, 
                Uri.parse("market://details?id=" + SERVICE_PACKAGE))
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        } catch (ActivityNotFoundException e) {
            // No Play Store (Chinese devices, Amazon)
            context.startActivity(new Intent(Intent.ACTION_VIEW,
                Uri.parse("https://play.google.com/store/apps/details?id=" + SERVICE_PACKAGE))
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        }
        return false;
    }

    private boolean isServiceInstalled() {
        try {
            context.getPackageManager().getPackageInfo(SERVICE_PACKAGE, 0);
            return true;
        } catch (PackageManager.NameNotFoundException e) {
            return false;
        }
    }

    public void connect(ServiceConnection callback) {
        Intent intent = new Intent();
        intent.setComponent(new ComponentName(SERVICE_PACKAGE, 
            SERVICE_PACKAGE + ".PubSubDaemonService"));
        context.bindService(intent, callback, Context.BIND_AUTO_CREATE);
    }
}
```

