## Implementation

### 1. Client-Side: Force Start + Bind

Android 10+ blocks background starts, but **bindService() is exempt** if the target app is already running. If not, you need to start it first:

```java
public class PubSubClient {
    private static final String SERVICE_PKG = "com.yourcompany.pubsub";
    private static final String SERVICE_CLASS = SERVICE_PKG + ".PubSubService";

    public void ensureRunningAndConnect(Context context, ConnectionCallback cb) {
        // Step 1: Check if service is already running
        if (isServiceRunning(context)) {
            bindToService(context, cb);
            return;
        }

        // Step 2: Start service explicitly (brings up the process)
        Intent intent = new Intent();
        intent.setComponent(new ComponentName(SERVICE_PKG, SERVICE_CLASS));

        // Android 8.0+ requires startForegroundService
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            context.startForegroundService(intent);
        } else {
            context.startService(intent);
        }

        // Step 3: Delay briefly then bind (give process time to init native code)
        new Handler(Looper.getMainLooper()).postDelayed(() -> {
            bindToService(context, cb);
        }, 500); // Tune this delay based on your native init time
    }

    private void bindToService(Context context, ConnectionCallback cb) {
        Intent intent = new Intent();
        intent.setComponent(new ComponentName(SERVICE_PKG, SERVICE_CLASS));

        context.bindService(intent, new ServiceConnection() {
            @Override
            public void onServiceConnected(ComponentName name, IBinder service) {
                IPubSubService ipc = IPubSubService.Stub.asInterface(service);

                // CRITICAL: Register death recipient
                try {
                    service.linkToDeath(() -> {
                        // Service died - notify client to retry
                        cb.onServiceDied();
                    }, 0);
                } catch (RemoteException e) {
                    e.printStackTrace();
                }

                cb.onConnected(ipc);
            }

            @Override
            public void onServiceDisconnected(ComponentName name) {
                cb.onDisconnected();
            }
        }, Context.BIND_AUTO_CREATE);
    }

    private boolean isServiceRunning(Context context) {
        ActivityManager am = (ActivityManager) context.getSystemService(Context.ACTIVITY_SERVICE);
        if (am != null) {
            for (ActivityManager.RunningServiceInfo service : am.getRunningServices(Integer.MAX_VALUE)) {
                if (SERVICE_CLASS.equals(service.service.getClassName())) {
                    return true;
                }
            }
        }
        return false;
    }
}
```

### 2. Service-Side: Stay Alive

Your service **must** be a foreground service with a persistent notification. Without this, Android will kill it within minutes:

```java
public class PubSubService extends Service {
    private static final int NOTIF_ID = 1;
    private static final String CHANNEL_ID = "pubsub_daemon";

    @Override
    public void onCreate() {
        super.onCreate();

        // CRITICAL: Must call within 5 seconds of startForegroundService()
        startForeground(NOTIF_ID, buildNotification());

        // Load native daemon
        System.loadLibrary("pubsub_daemon");
        nativeInit();
    }

    private Notification buildNotification() {
        createNotificationChannel();

        return new NotificationCompat.Builder(this, CHANNEL_ID)
            .setContentTitle("Pub/Sub Network Active")
            .setContentText("Running - required by connected apps")
            .setSmallIcon(R.drawable.ic_daemon)
            .setOngoing(true)  // Cannot be swiped away
            .setSilent(true)  // No sound/vibration
            .build();
    }

    @Override
    public IBinder onBind(Intent intent) {
        // Return your native Binder from JNI
        return nativeGetBinder();
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        // STICKY: restart if killed (best effort, not guaranteed)
        return START_STICKY;
    }
}
```

### 3. Handle Service Death

When the service dies (killed by system or crash), clients must detect and reconnect:

```java
public class ReliablePubSubConnection {
    private IPubSubService service;
    private boolean shouldReconnect = true;
    private final Handler reconnectHandler = new Handler(Looper.getMainLooper());

    public void connect(Context context) {
        Intent intent = new Intent();
        intent.setComponent(new ComponentName(SERVICE_PKG, SERVICE_CLASS));

        context.bindService(intent, new ServiceConnection() {
            @Override
            public void onServiceConnected(ComponentName name, IBinder binder) {
                service = IPubSubService.Stub.asInterface(binder);

                try {
                    binder.linkToDeath(new IBinder.DeathRecipient() {
                        @Override
                        public void binderDied() {
                            service = null;
                            if (shouldReconnect) {
                                scheduleReconnect(context);
                            }
                        }
                    }, 0);
                } catch (RemoteException e) {
                    e.printStackTrace();
                }
            }

            @Override
            public void onServiceDisconnected(ComponentName name) {
                service = null;
            }
        }, Context.BIND_AUTO_CREATE);
    }

    private void scheduleReconnect(Context context) {
        // Exponential backoff: 1s, 2s, 4s, 8s... max 60s
        reconnectHandler.postDelayed(() -> connect(context), 1000);
    }
}
```

